  W("Sunday", "/ˈsʌndeɪ/", "noun", "неділя", "See you on Sunday.", "До неділі."),
  W("weekend", "/ˌwiːkˈend/", "noun", "вихідні", "I'm at home at the weekend.", "На вихідних я вдома."),
  W("free", "/friː/", "adjective", "вільний", "I'm free today.", "Я сьогодні вільний."),
  W("busy", "/ˈbɪzi/", "adjective", "зайнятий", "I'm busy on Monday.", "У понеділок я зайнятий."),
