  fb("I'm busy ___ nine o'clock.", ["at", "on", "in"], "Перед годиною — at. Не плутайте: on Saturday, але at nine."),
  liu("I'm busy on Sunday.", "Прослухайте. Що каже людина?", ["У неділю я зайнятий", "У суботу я зайнятий", "У неділю я вільний"], "Busy — зайнятий, on Sunday — у неділю."),
  mcu("Що означає every Friday?", ["Кожної п'ятниці", "Цієї п'ятниці", "Наступної п'ятниці"], "Every — кожен."),
  bs("Я вільний у суботу.", ["I'm", "free", "on", "Saturday"], ["at", "busy"], "I'm free on Saturday."),
  tr("У понеділок я зайнятий.", ["I'm busy on Monday", "I am busy on Monday", "On Monday I'm busy", "On Monday I am busy"], "I'm busy on Monday."),
